/**
 * Spring Initializr client.
 *
 * Spring Boot projects are generated by the Initializr service rather than from
 * local templates. This keeps dependency ids, Boot versions and the Maven/Gradle
 * build files in lockstep with what start.spring.io produces — the same source
 * the IntelliJ IDEA wizard uses.
 *
 * The response is a zip (or tar.gz) archive that is unpacked in memory, so the
 * whole generation stays pure and works with `--dry-run`.
 */

import { INITIALIZR_BASE_URL } from '../versions.js';
import type { FileMap } from '../writer.js';
import { extractArchive } from '../util/archive.js';
import type { ProjectConfig } from '../types.js';

/** The metadata document returned by Initializr. */
export interface InitializrMetadata {
  bootVersion: { default: string; values: { id: string; name: string }[] };
  javaVersion: { default: string; values: { id: string; name: string }[] };
  language: { default: string; values: { id: string; name: string }[] };
  packaging: { default: string; values: { id: string; name: string }[] };
  type: {
    default: string;
    values: { id: string; name: string; action: string; tags?: Record<string, string> }[];
  };
  dependencies: {
    values: {
      name: string;
      default?: boolean;
      values: {
        id: string;
        name: string;
        description?: string;
        tags?: string[];
      }[];
    }[];
  };
}

export interface InitializrResult {
  files: FileMap;
  /** Where the archive came from, for reporting. */
  source: string;
}

export interface FetchOptions {
  /** Abort the request after this long. */
  timeoutMs?: number;
  /** Override the service base URL. */
  baseUrl?: string;
}

const ACCEPT_METADATA = 'application/vnd.initializr.v2.2+json';

/**
 * Fetch and parse the Initializr metadata document.
 *
 * @throws when the service is unreachable or returns an unexpected payload.
 */
export async function fetchMetadata(options: FetchOptions = {}): Promise<InitializrMetadata> {
  const { timeoutMs = 20_000, baseUrl = INITIALIZR_BASE_URL } = options;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(baseUrl, {
      headers: { Accept: ACCEPT_METADATA },
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(`Initializr metadata request failed with HTTP ${response.status}`);
    }
    return (await response.json()) as InitializrMetadata;
  } finally {
    clearTimeout(timer);
  }
}

/** Map the selected build tool and DSL to an Initializr project `type`. */
export function initializrType(config: ProjectConfig): string {
  if (config.buildTool === 'maven') return 'maven-project';
  return config.dsl === 'kotlin' ? 'gradle-project-kotlin' : 'gradle-project';
}

/** Build the `starter.zip` query string for a configuration. */
export function initializrQuery(config: ProjectConfig): URLSearchParams {
  const params = new URLSearchParams();
  params.set('type', initializrType(config));
  params.set('language', config.language);
  params.set('bootVersion', config.bootVersion);
  params.set('groupId', config.groupId);
  params.set('artifactId', config.artifactId);
  params.set('version', config.version);
  // Initializr derives the application class name from `name`, while the local
  // Maven/Gradle generators derive it from `artifactId`. Sending the artifactId
  // here keeps every generator producing the same class name for the same
  // configuration, so `--artifact-id orders` yields OrdersApplication whichever
  // build system is chosen.
  params.set('name', config.artifactId);
  params.set('description', config.description);
  params.set('packageName', config.packageName);
  params.set('packaging', config.packaging);
  params.set('javaVersion', config.javaVersion);
  // `configurationFileFormat` selects application.properties vs application.yaml.
  params.set('configurationFileFormat', config.configFormat);
  if (config.bootDependencies.length > 0) {
    params.set('dependencies', config.bootDependencies.join(','));
  }
  return params;
}

/**
 * Ask Initializr for a project archive and unpack it into a file map.
 *
 * @throws when the service is unreachable or returns a non-archive payload.
 */
export async function fetchInitializrProject(
  config: ProjectConfig,
  options: FetchOptions = {},
): Promise<InitializrResult> {
  const { timeoutMs = 60_000, baseUrl = INITIALIZR_BASE_URL } = options;
  const params = initializrQuery(config);
  const url = `${baseUrl}/starter.zip?${params.toString()}`;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let buffer: Buffer;
  try {
    const response = await fetch(url, { signal: controller.signal });
    if (!response.ok) {
      const detail = await response.text().catch(() => '');
      throw new Error(
        `Initializr returned HTTP ${response.status}${detail ? `: ${detail.slice(0, 200)}` : ''}`,
      );
    }
    buffer = Buffer.from(await response.arrayBuffer());
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    throw new Error(`could not reach Spring Initializr at ${baseUrl} (${reason})`);
  } finally {
    clearTimeout(timer);
  }

  const files = await extractArchive(buffer);
  return { files, source: url };
}

/**
 * Find a leading directory shared by every entry.
 *
 * Initializr archives are flat, but GitHub tarballs nest everything under
 * `<repo>-<ref>/`; stripping that prefix makes both usable identically.
 */
export function commonPrefix(paths: string[]): string {
  if (paths.length === 0) return '';
  const first = paths[0] ?? '';
  const firstSegmentEnd = first.indexOf('/');
  if (firstSegmentEnd === -1) return '';
  const candidate = first.slice(0, firstSegmentEnd + 1);
  if (!paths.every((p) => p.startsWith(candidate))) return '';
  return candidate;
}

/** Strip a shared leading directory from an extracted file map. */
export function stripCommonPrefix(files: FileMap): FileMap {
  const prefix = commonPrefix([...files.keys()]);
  if (!prefix) return files;
  const out: FileMap = new Map();
  for (const [entryPath, content] of files) {
    const relative = entryPath.slice(prefix.length);
    if (relative) out.set(relative, content);
  }
  return out;
}
